import create from 'zustand'
import { persist } from 'zustand/middleware'

interface PomodoroState {
  sessionLength: number; // in minutes
  breakLength: number;
  isRunning: boolean;
  isSession: boolean;
  timeLeft: number; // in seconds
  start: () => void;
  pause: () => void;
  reset: () => void;
  toggleSession: () => void;
  setSessionLength: (m: number) => void;
  setBreakLength: (m: number) => void;
}

export const useStore = create<PomodoroState>()
  (persist(
    (set, get) => ({
      sessionLength: 25,
      breakLength: 5,
      isRunning: false,
      isSession: true,
      timeLeft: 25 * 60,
      start: () => set({ isRunning: true }),
      pause: () => set({ isRunning: false }),
      reset: () => {
        set({ isRunning: false, isSession: true, timeLeft: get().sessionLength * 60 })
      },
      toggleSession: () => {
        const { isSession, sessionLength, breakLength } = get()
        const nextIsSession = !isSession
        const newTime = nextIsSession ? sessionLength * 60 : breakLength * 60
        set({ isSession: nextIsSession, timeLeft: newTime })
      },
      setSessionLength: (m) => {
        set({ sessionLength: m })
        if (get().isSession) {
          set({ timeLeft: m * 60 })
        }
      },
      setBreakLength: (m) => set({ breakLength: m }),
    }),
    {
      name: 'pomodoro-storage',
    }
  ))

