import { useEffect } from 'react';
import { format } from 'date-fns';
import { useStore } from '../store';

export const Timer = () => {
  const { timeLeft, isRunning, isSession, toggleSession, pause } = useStore();

  // Countdown effect
  useEffect(() => {
    if (!isRunning) return;
    const timer = setInterval(() => {
      useStore.setState((state) => {
        if (state.timeLeft <= 1) {
          // Session finished
          const next = state.isSession ? state.breakLength * 60 : state.sessionLength * 60;
          return { timeLeft: next, isSession: !state.isSession };
        }
        return { timeLeft: state.timeLeft - 1 };
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [isRunning]);

  const minutes = Math.floor(timeLeft / 60);
  const seconds = timeLeft % 60;
  const formatted = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;

  return (
    <div className="text-6xl font-mono text-center">
      {formatted}
    </div>
  );
};

