import create from 'zustand'
import { persist } from 'zustand/middleware'

export interface TimerState {
  sessionLength: number // minutes
  breakLength: number
  timeLeft: number // seconds
  isRunning: boolean
  isSession: boolean
  start: () => void
  pause: () => void
  reset: () => void
  setSessionLength: (len: number) => void
  setBreakLength: (len: number) => void
}

export const useStore = create<TimerState>()(
  persist(
    (set, get) => ({
      sessionLength: 25,
      breakLength: 5,
      timeLeft: 25 * 60,
      isRunning: false,
      isSession: true,
      start: () => set({ isRunning: true }),
      pause: () => set({ isRunning: false }),
      reset: () => {
        const { isSession } = get()
        set({
          isRunning: false,
          timeLeft: isSession ? get().sessionLength * 60 : get().breakLength * 60,
          isSession: isSession,
        })
      },
      setSessionLength: (len) => {
        set({ sessionLength: len })
        if (get().isSession) {
          set({ timeLeft: len * 60 })
        }
      },
      setBreakLength: (len) => {
        set({ breakLength: len })
        if (!get().isSession) {
          set({ timeLeft: len * 60 })
        }
      },
    }),
    {
      name: 'pomodoro-store',
      getStorage: () => localStorage,
    },
  ),
)

